(function(){
'use strict';
const P=RWPixel,L=(zh,en)=>RWI18n.lang==='en'?en:zh,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palettes=['#25352b','#45583d','#6f8055','#9aaa74','#c5c995','#d6ab6d','#b9663f','#6a422f','#26353d','#526b74','#8caeb3','#e3e9d5','#ffffff','#000000','#00ff00','#f34e42'];
let p,kind,tool='pen',ink=palettes[2],zoom=12,grid=true,mirror=false,onion=false,hist=[],pos=-1,drag=null,timer,importIncoming=null;
const $=s=>document.querySelector(s),button=(a,zh,en,extra='')=>`<button class="btn btn-small btn-plain" data-art="${a}" ${extra}>${L(zh,en)}</button>`;
function notice(text){window.toast?toast(text):console.info(text)}
function key(){return 'rwlab-pixel-'+kind+'-v1'}
function persist(){try{localStorage.setItem(key(),JSON.stringify(p));const s=$('#art-save');if(s)s.textContent=L('已保存在此浏览器','Saved in this browser');return true}catch{const s=$('#art-save');if(s)s.textContent=L('空间不足，请导出项目备份','Storage full, export your project');return false}}
function checkpoint(){const s=JSON.stringify(p);if(hist[pos]!==s){hist=hist.slice(0,pos+1);hist.push(s);if(hist.length>30)hist.shift();pos=hist.length-1}persist();const u=$('[data-art=undo]'),r=$('[data-art=redo]');if(u)u.disabled=pos<=0;if(r)r.disabled=pos>=hist.length-1}
function current(){return p.frames[p.frame].layers[p.layer]}
function offscreen(frame=p.frame){const c=document.createElement('canvas');c.width=p.width;c.height=p.height;c.getContext('2d').putImageData(new ImageData(P.bytes(P.flatten(p,frame)),p.width,p.height),0,0);return c}
function imageCanvas(pixels){const c=document.createElement('canvas');c.width=p.width;c.height=p.height;c.getContext('2d').putImageData(new ImageData(P.bytes(pixels),p.width,p.height),0,0);return c}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function saveCanvas(c,name){c.toBlob(b=>{if(b)saveBlob(b,name);else notice(L('图片导出失败','Image export failed'))},'image/png')}
function filename(){return p.title.replace(/[^\w-]/g,'_').slice(0,60)||kind}
function load(kind){try{const v=localStorage.getItem('rwlab-pixel-'+kind+'-v1');if(v)return P.validate(JSON.parse(v))}catch{}const project=P.create(kind,kind==='map'?20:32);if(kind==='unit'){const l=project.frames[0].layers[1],w=project.width;for(let y=7;y<26;y++)for(let x=7;x<25;x++)l.pixels[y*w+x]=P.color(x<11||x>20?'#25352b':y<10?'#9aaa74':'#6f8055');const t=project.frames[0].layers[2];for(let y=4;y<20;y++)for(let x=y<13?15:12;x<(y<13?17:20);x++)t.pixels[y*w+x]=P.color(y<13?'#c5c995':'#45583d')}else{project.frames[0].layers[0].pixels.fill(P.color('#6f8055'));for(let i=0;i<35;i++)project.frames[0].layers[0].pixels[(i*79)%400]=P.color('#9aaa74')}return project}
function mount(mode){dispose();kind=mode==='map-art'?'map':'unit';p=load(kind);hist=[];pos=-1;zoom=kind==='map'?18:12;checkpoint();render();if(importIncoming){const pending=importIncoming;importIncoming=null;importData(pending).catch(e=>notice(e.message))}}
function render(){if(!p)return;const map=kind==='map';$('#main').innerHTML=`<div class="creative-shell"><div class="creative-title"><div><a class="ed-back" href="#editors">← ${L('创作工具','Creative tools')}</a><div class="eyebrow">${map?'TERRAIN / TILE STUDIO':'UNITS / PIXEL STUDIO'}</div><h1>${map?L('地图图片编辑器','Map image editor'):L('单位图片编辑器','Unit image editor')}</h1><p>${map?L('先画地块，再把它们拼成地图，随时检查边缘能否自然衔接','Draw tiles, arrange a map and check how the edges fit together'):L('从小小一张像素画开始，用图层和动画帧做出自己的单位','Make a unit sprite, one pixel at a time, with layers and animation frames')}</p></div><a class="btn btn-orange" href="#ai-art">✦ ${L('让 AI 帮我画','Draw with AI')}</a></div><div class="art-toolbar"><label>${L('文件名','Filename')}<input id="art-name" value="${E(p.title)}" maxlength="60"></label><label>${L(map?'地块大小':'画布大小',map?'Tile size':'Canvas size')}<select id="art-size">${[16,20,24,32,48,64,96,128].map(n=>`<option value="${n}" ${p.width===n?'selected':''}>${n} × ${n}</option>`).join('')}</select></label>${button('undo','撤销','Undo',pos<=0?'disabled':'')}${button('redo','重做','Redo',pos>=hist.length-1?'disabled':'')}${button('import','导入 PNG / 项目','Import PNG / project')}${button('project','保存项目','Save project')}${button('png',map?'导出地块 PNG':'导出当前帧 PNG',map?'Export tile PNG':'Export frame PNG')}${button('sheet',map?'导出地块图集':'导出动画帧图',map?'Export tile atlas':'Export sprite sheet')}<input type="file" id="art-file" accept="image/png,image/webp,image/jpeg,.json" hidden></div><div class="art-layout"><aside class="art-tools"><h2>${L('画笔工具','Drawing tools')}</h2><div class="art-tool-grid">${[['pen','✎','铅笔','Pencil'],['erase','◇','橡皮','Eraser'],['fill','▨','填充','Fill'],['pick','⊕','取色','Eyedropper'],['line','╱','直线','Line'],['rect','□','矩形','Rectangle']].map(([id,s,z,e])=>`<button data-art="tool" data-value="${id}" class="${tool===id?'active':''}" aria-pressed="${tool===id}"><b>${s}</b>${L(z,e)}</button>`).join('')}</div><label class="art-ink">${L('颜色','Color')}<input type="color" id="art-color" value="${ink}"></label><div class="art-palette">${palettes.map(c=>`<button style="background:${c}" data-art="color" data-value="${c}" aria-label="${c}"></button>`).join('')}</div><label><input id="art-mirror" type="checkbox" ${mirror?'checked':''}> ${L('左右对称','Mirror horizontally')}</label><label><input id="art-grid" type="checkbox" ${grid?'checked':''}> ${L('显示像素网格','Pixel grid')}</label>${!map?`<label><input id="art-onion" type="checkbox" ${onion?'checked':''}> ${L('淡显上一帧','Onion skin')}</label>`:''}<label>${L('缩放','Zoom')}<input id="art-zoom" type="range" min="2" max="24" value="${zoom}"></label><div class="art-tool-actions">${button('flip','水平翻转','Flip horizontally')}${button('clear','清空当前图层','Clear layer')}${button('cutout','去除边缘底色','Remove edge background')}</div><p class="art-tip">${L('绿色 #00ff00 可用来绘制队伍色区域，透明区域不会出现在 PNG 里','Use #00ff00 for team-color areas, transparent pixels stay transparent in the PNG')}</p></aside><section class="art-stage-panel"><div class="art-stage-meta"><span>${p.width} × ${p.height} px</span><span id="art-save">${L('已保存在此浏览器','Saved in this browser')}</span></div><div class="art-stage" id="art-stage"><canvas id="art-canvas" aria-label="${L('像素画布，可用鼠标或触控笔绘制','Pixel canvas, draw with a mouse or stylus')}"></canvas></div><div class="art-frame-head"><strong>${L(map?'地块素材':'动画帧',map?'Tiles':'Animation frames')}</strong><div>${button('add-frame',map?'新地块':'新帧',map?'New tile':'New frame')}${button('clone-frame','复制','Duplicate')}${button('remove-frame','移除','Remove',p.frames.length<=1?'disabled':'')}</div></div><div class="art-frames">${p.frames.map((f,i)=>`<button data-art="frame" data-value="${i}" class="${p.frame===i?'active':''}"><canvas width="${p.width}" height="${p.height}" data-thumb="${i}"></canvas><span>${i+1}</span></button>`).join('')}</div>${map?mapMarkup():`<div class="art-preview-row"><canvas id="art-animation" width="${p.width}" height="${p.height}"></canvas><label>${L('预览速度','Playback speed')}<input type="number" id="art-fps" min="1" max="24" value="${p.fps}"> FPS</label><p>${L('帧图按从左到右排列，PNG 中保留透明背景','Frames are exported left to right, with transparency preserved')}</p></div>`}</section><aside class="art-properties"><h2>${L('图层','Layers')}</h2><div class="art-layers">${p.frames[p.frame].layers.map((l,i)=>`<div class="${p.layer===i?'active':''}"><button data-art="visibility" data-value="${i}" aria-label="${L('显示或隐藏图层','Show or hide layer')}">${l.visible?'◉':'○'}</button><button data-art="layer" data-value="${i}">${E(layerLabel(l.name))}</button></div>`).reverse().join('')}</div><div class="art-layer-actions">${button('add-layer','＋ 图层','＋ Layer')}${button('rename-layer','重命名','Rename')}${button('layer-up','上移','Move up')}${button('layer-down','下移','Move down')}${button('remove-layer','删除图层','Delete layer',p.frames[p.frame].layers.length<=1?'disabled':'')}</div><h3>${L('用到模组里','Use in a mod')}</h3><pre class="art-recipe" data-no-translate>${E(recipe())}</pre>${!map?button('send-unit','添加到单位素材','Add to unit assets'):''}<p class="art-tip">${map?L('地图图片是视觉素材，任务目标、增援和胜利条件请在地图触发器中设置','Map images are visual assets, use the trigger editor for objectives, reinforcements and victory conditions'):L('以实际像素大小查看边缘，枪管和炮塔也可以拆成单独图片','Check the edges at actual size, barrels and turrets can use separate images')}</p><a class="text-link" href="${map?'#map-editor':'#unit-editor'}">${L('继续编辑代码 →','Continue editing code →')}</a><p class="art-credit">${L('操作参考','Interaction references')} <a href="https://www.piskelapp.com/" target="_blank" rel="noopener">Piskel</a> · <a href="https://www.mapeditor.org/" target="_blank" rel="noopener">Tiled</a> · <a href="https://pixelorama.org/" target="_blank" rel="noopener">Pixelorama</a></p></aside></div></div>`;bind();draw();for(const canvas of document.querySelectorAll('[data-thumb]'))canvas.getContext('2d').drawImage(offscreen(Number(canvas.dataset.thumb)),0,0);if(map)drawMap();else startAnimation()}
function layerLabel(name){return ({Shadow:L('阴影','Shadow'),Body:L('车身','Body'),Turret:L('炮塔','Turret'),Terrain:L('地形','Terrain')})[name]||name}
function recipe(){return kind==='map'?L('地块图集 → 地图贴图\n地图预览 → 整张 PNG\n拼图项目 → 可继续编辑的 JSON','Tile atlas → map textures\nMap preview → full PNG\nProject → editable JSON'):`[graphics]\nimage: ${filename()}.png\ntotal_frames: ${p.frames.length}\nimage_wreak: NONE\nimage_shadow: AUTO${p.frames.length>1?'\nanimation_moving_start: 0\nanimation_moving_end: '+(p.frames.length-1)+'\nanimation_moving_speed: 6':''}`}
function mapMarkup(){return `<div class="art-map-head"><h2>${L('地块拼接预览','Tile map preview')}</h2><div><label>${L('列','Columns')}<input id="art-map-w" type="number" min="1" max="64" value="${p.map.width}"></label><label>${L('行','Rows')}<input id="art-map-h" type="number" min="1" max="64" value="${p.map.height}"></label>${button('map-size','调整网格','Resize grid')}${button('map-fill','铺满当前地块','Fill with selected tile')}${button('map-png','导出地图 PNG','Export map PNG')}${button('tile-preview','查看无缝拼接','Preview repeating tile')}</div></div><p class="art-tip">${L('选择上方地块，在下方网格中拖动铺设','Select a tile above, then drag across the grid to paint it')}</p><div class="art-map-stage"><canvas id="art-map-canvas" aria-label="${L('地图地块拼接画布','Tile map painting canvas')}"></canvas></div>`}
function draw(){const c=$('#art-canvas');if(!c)return;c.width=p.width*zoom;c.height=p.height*zoom;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,c.width,c.height);if(onion&&p.frame>0&&kind==='unit'){ctx.globalAlpha=.22;ctx.drawImage(offscreen(p.frame-1),0,0,c.width,c.height);ctx.globalAlpha=1}ctx.drawImage(offscreen(),0,0,c.width,c.height);if(grid&&zoom>=5){ctx.strokeStyle='rgba(60,75,65,.22)';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<=p.width;x++){ctx.moveTo(x*zoom+.5,0);ctx.lineTo(x*zoom+.5,c.height)}for(let y=0;y<=p.height;y++){ctx.moveTo(0,y*zoom+.5);ctx.lineTo(c.width,y*zoom+.5)}ctx.stroke()}const thumb=$(`[data-thumb="${p.frame}"]`);if(thumb){const x=thumb.getContext('2d');x.clearRect(0,0,p.width,p.height);x.drawImage(offscreen(),0,0)}if(kind==='map')drawMap()}
function mapCanvas(){const m=p.map,c=document.createElement('canvas');c.width=m.width*p.width;c.height=m.height*p.height;const ctx=c.getContext('2d'),tiles=p.frames.map((_,i)=>offscreen(i));m.cells.forEach((n,i)=>ctx.drawImage(tiles[n]||tiles[0],i%m.width*p.width,Math.floor(i/m.width)*p.height));return c}
function drawMap(){const c=$('#art-map-canvas');if(!c)return;const src=mapCanvas();c.width=src.width;c.height=src.height;c.getContext('2d').drawImage(src,0,0);c.style.width=Math.min(680,c.width*2)+'px'}
function startAnimation(){clearInterval(timer);let i=0;timer=setInterval(()=>{const c=$('#art-animation');if(!c)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,p.width,p.height);ctx.drawImage(offscreen(i++%p.frames.length),0,0)},1000/p.fps)}
function coords(e,c,unit=1){const r=c.getBoundingClientRect();return [Math.min(Math.ceil(c.width/unit)-1,Math.max(0,Math.floor((e.clientX-r.left)*c.width/r.width/unit))),Math.min(Math.ceil(c.height/unit)-1,Math.max(0,Math.floor((e.clientY-r.top)*c.height/r.height/unit)))]}
function paint(e){const c=$('#art-canvas'),to=coords(e,c,zoom),px=current().pixels,w=p.width,h=p.height,color=tool==='erase'?0:P.color(ink);if(tool==='pick'){ink=P.hex(P.flatten(p)[to[1]*w+to[0]]);$('#art-color').value=ink;return}if(tool==='fill'){P.fill(px,w,h,...to,color);return}if(['line','rect'].includes(tool)){current().pixels=drag.base.slice();const pixels=current().pixels;if(tool==='line')P.line(pixels,w,h,drag.start,to,color,mirror);else{const [x,y]=drag.start,[a,b]=to;P.line(pixels,w,h,[x,y],[a,y],color,mirror);P.line(pixels,w,h,[a,y],[a,b],color,mirror);P.line(pixels,w,h,[a,b],[x,b],color,mirror);P.line(pixels,w,h,[x,b],[x,y],color,mirror)}}else P.line(px,w,h,drag.last,to,color,mirror);drag.last=to}
function bind(){const c=$('#art-canvas');c.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();c.setPointerCapture(e.pointerId);const start=coords(e,c,zoom);drag={start,last:start,base:current().pixels.slice()};paint(e);draw()});c.addEventListener('pointermove',e=>{if(!drag||!c.hasPointerCapture(e.pointerId)||['fill','pick'].includes(tool))return;paint(e);draw()});const finish=()=>{if(drag){drag=null;checkpoint()}};c.addEventListener('pointerup',finish);c.addEventListener('pointercancel',finish);const m=$('#art-map-canvas');if(m){let painting=false;const place=e=>{const r=m.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*p.map.width),y=Math.floor((e.clientY-r.top)/r.height*p.map.height);if(x>=0&&y>=0&&x<p.map.width&&y<p.map.height)p.map.cells[y*p.map.width+x]=p.frame;drawMap()};m.addEventListener('pointerdown',e=>{e.preventDefault();m.setPointerCapture(e.pointerId);painting=true;place(e)});m.addEventListener('pointermove',e=>{if(painting)place(e)});for(const t of ['pointerup','pointercancel'])m.addEventListener(t,()=>{painting=false;checkpoint()})}}
async function importData(data){const img=new Image();img.src=data;await img.decode();const c=document.createElement('canvas');c.width=p.width;c.height=p.height;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;const s=Math.min(p.width/img.width,p.height/img.height),w=Math.max(1,Math.round(img.width*s)),h=Math.max(1,Math.round(img.height*s));ctx.drawImage(img,Math.floor((p.width-w)/2),Math.floor((p.height-h)/2),w,h);if(p.frames[p.frame].layers.length>=8)throw Error(L('图层已满，请删除一个图层再导入','Remove a layer before importing another'));p.frames[p.frame].layers.push({name:L('导入图片','Imported image'),visible:true,pixels:P.fromBytes(ctx.getImageData(0,0,p.width,p.height).data)});p.layer=p.frames[p.frame].layers.length-1;checkpoint();render();notice(L('已添加到新图层，可撤销或去除底色','Added on a new layer, you can undo or remove its background'))}
async function handle(b){const a=b.dataset.art;if(a==='tool'){tool=b.dataset.value;render();return}if(a==='color'){ink=b.dataset.value;$('#art-color').value=ink;return}if(a==='undo'||a==='redo'){pos=Math.max(0,Math.min(hist.length-1,pos+(a==='undo'?-1:1)));p=JSON.parse(hist[pos]);persist();render();return}if(a==='import'){$('#art-file').click();return}if(a==='project'){saveBlob(new Blob([JSON.stringify(p)],{type:'application/json'}),filename()+'.rwart.json');return}if(a==='png'){saveCanvas(offscreen(),filename()+'.png');return}if(a==='sheet'){const c=document.createElement('canvas');c.width=p.width*p.frames.length;c.height=p.height;const ctx=c.getContext('2d');p.frames.forEach((_,i)=>ctx.drawImage(offscreen(i),i*p.width,0));saveCanvas(c,filename()+'.png');return}if(a==='frame'){p.frame=Number(b.dataset.value);p.layer=Math.min(p.layer,p.frames[p.frame].layers.length-1);persist();render();return}if(a==='layer'){p.layer=Number(b.dataset.value);persist();render();return}if(a==='add-frame'||a==='clone-frame'){if(p.frames.length>=24)throw Error(L('最多 24 帧','Up to 24 frames'));p.frames.push(a==='clone-frame'?P.clone(p.frames[p.frame]):{layers:p.frames[p.frame].layers.map(l=>P.layer(p.width,p.height,l.name))});p.frame=p.frames.length-1}if(a==='remove-frame'&&p.frames.length>1){const old=p.frame;p.frames.splice(old,1);p.map.cells=p.map.cells.map(n=>n===old?0:n>old?n-1:n);p.frame=Math.min(old,p.frames.length-1);p.layer=Math.min(p.layer,p.frames[p.frame].layers.length-1)}if(a==='visibility')p.frames[p.frame].layers[Number(b.dataset.value)].visible=!p.frames[p.frame].layers[Number(b.dataset.value)].visible;if(a==='add-layer'){if(p.frames[p.frame].layers.length>=8)throw Error(L('最多 8 个图层','Up to 8 layers'));p.frames[p.frame].layers.push(P.layer(p.width,p.height,L('新图层','New layer')));p.layer=p.frames[p.frame].layers.length-1}if(a==='rename-layer'){const name=prompt(L('图层名称','Layer name'),current().name);if(name===null)return;current().name=name.slice(0,60)||'Layer'}if(a==='remove-layer'&&p.frames[p.frame].layers.length>1){p.frames[p.frame].layers.splice(p.layer,1);p.layer=Math.max(0,p.layer-1)}if(a==='layer-up'||a==='layer-down'){const ls=p.frames[p.frame].layers,i=p.layer,j=i+(a==='layer-up'?1:-1);if(j>=0&&j<ls.length){[ls[i],ls[j]]=[ls[j],ls[i]];p.layer=j}}if(a==='clear')current().pixels.fill(0);if(a==='flip'){const px=current().pixels;for(let y=0;y<p.height;y++)for(let x=0;x<Math.floor(p.width/2);x++){const a=y*p.width+x,b=y*p.width+p.width-x-1;[px[a],px[b]]=[px[b],px[a]]}}if(a==='cutout')P.removeBackground(current().pixels,p.width,p.height,28);if(a==='map-size'){const w=Number($('#art-map-w').value),h=Number($('#art-map-h').value);if(![w,h].every(n=>Number.isInteger(n)&&n>=1&&n<=64))throw Error(L('行列范围为 1–64','Use 1–64 rows and columns'));const old=p.map;p.map={width:w,height:h,cells:Array.from({length:w*h},(_,i)=>i%w<old.width&&Math.floor(i/w)<old.height?old.cells[Math.floor(i/w)*old.width+i%w]:0)}}if(a==='map-fill')p.map.cells.fill(p.frame);if(a==='map-png'){saveCanvas(mapCanvas(),filename()+'-map.png');return}if(a==='tile-preview'){const d=document.createElement('dialog');d.className='tile-dialog';d.innerHTML=`<h2>${L('当前地块 · 无缝预览','Selected tile · repeating preview')}</h2><div class="tile-repeat" style="background-image:url('${offscreen().toDataURL()}');background-size:${p.width*4}px ${p.height*4}px"></div><button class="btn btn-dark">${L('继续绘制','Continue drawing')}</button>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();return}if(a==='send-unit'){await RWEditor.addAsset({name:filename()+'.png',mime:'image/png',data:offscreen().toDataURL().split(',')[1]});notice(L('图片已加入单位素材，可在图像模块中选择','Image added to unit assets, select it in Graphics'));return}checkpoint();render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-art]');if(b&&p)Promise.resolve(handle(b)).catch(e=>notice(e.message))});
document.addEventListener('input',e=>{if(e.target.id==='art-color')ink=e.target.value;if(e.target.id==='art-zoom'){zoom=Number(e.target.value);draw()}});
document.addEventListener('change',async e=>{if(!p)return;try{const id=e.target.id,v=e.target.value;if(id==='art-name'){p.title=v;checkpoint();render()}if(id==='art-size'){p=P.resize(p,Number(v),Number(v));checkpoint();render()}if(id==='art-mirror')mirror=e.target.checked;if(id==='art-grid'){grid=e.target.checked;draw()}if(id==='art-onion'){onion=e.target.checked;draw()}if(id==='art-fps'){p.fps=Math.max(1,Math.min(24,Number(v)||6));checkpoint();startAnimation()}if(id==='art-file'){const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error(L('文件最多 20 MB','Files must be under 20 MB'));if(file.name.endsWith('.json')){const next=P.validate(JSON.parse(await file.text()));if(next.kind!==kind)throw Error(L('请在对应的单位或地图图片编辑器中打开','Open this file in the matching unit or map image editor'));p=next;checkpoint();render()}else{const url=URL.createObjectURL(file);try{await importData(url)}finally{URL.revokeObjectURL(url)}}}}catch(err){notice(err.message)}});
function dispose(){clearInterval(timer);drag=null;if(p)persist();p=null}
window.addEventListener('rw-before-language-change',e=>{if(p&&!persist()){e.preventDefault();notice(L('请先保存图片项目再切换语言','Save your image project before changing language'))}});
window.RWStudio={mount,dispose,receive(data,mode='unit'){importIncoming=data;const hash=mode==='map'?'#map-art':'#unit-art';if(location.hash===hash){const next=importIncoming;importIncoming=null;return importData(next)}location.hash=hash}};
})();
